"""Reconstruct July 2023 revenue from warehouse dispatches and sensor logs."""

import csv
import json
from collections import defaultdict
from decimal import Decimal
from pathlib import Path


DATA_DIR = Path("/app/dataset")
DISPOSAL_TIMESTAMP = "2023-07-18 03:17:00"


def read_csv(name: str) -> list[dict[str, str]]:
    with (DATA_DIR / name).open(newline="") as file:
        return list(csv.DictReader(file))


def number(value: str) -> Decimal:
    return Decimal(value.replace(",", "."))


def answer() -> int:
    catalog = read_csv("product_catalog.csv")
    by_product_id = {row["product_id"]: row for row in catalog}
    by_ean = {row["ean_code"]: row for row in catalog}
    max_safe_temp = {
        row["storage_category"].casefold(): Decimal(row["max_safe_temp_c"])
        for row in catalog
    }

    unsafe_zones = defaultdict(set)
    for row in read_csv("temperature_logs.csv"):
        zone = row["zone"].casefold()
        if number(row["temperature_c"]) > max_safe_temp[zone]:
            unsafe_zones[row["timestamp"]].add(zone)

    # Both affected zones were unsafe before and after the 03:17 dispatch batch.
    affected_zones = {"meat", "frozen"}
    for reading_time in ("2023-07-18 02:00:00", "2023-07-18 04:00:00"):
        assert affected_zones <= unsafe_zones[reading_time]

    revenue = Decimal(0)
    disposal_value = Decimal(0)
    disposal_count = 0
    for dispatch in read_csv("warehouse_dispatches.csv"):
        product = by_product_id.get(dispatch["product_id"])
        if product is None:
            product = by_ean[dispatch["product_id"]]

        value = int(dispatch["quantity"]) * number(product["unit_price"])
        if dispatch["timestamp"] == DISPOSAL_TIMESTAMP:
            assert product["storage_category"].casefold() in affected_zones
            disposal_value += value
            disposal_count += 1
        else:
            # Each dispatch ID is a separate warehouse record, even if other
            # fields happen to match another record.
            revenue += value

    assert disposal_count == 8 and disposal_value == Decimal(10000)
    assert revenue == int(revenue)
    return int(revenue)


if __name__ == "__main__":
    with open("/app/answer.json", "w") as file:
        json.dump(answer(), file)
